```ts
export async function enableAutoMergeOnPr(opts: {
  prUrl: string
  expectedHeadSha?: string
  cwd?: string
  /** Backoff in ms tussen directe-merge-pogingen (injecteerbaar; 0 in tests). */
  directMergeBackoffMs?: number
}): Promise<EnableAutoMergeResult> {
  let prRef
  try {
    prRef = parseForgejoPrUrl(opts.prUrl)
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  try {
    const discovery = await discoverForgejo(prRef.host)
    if (!discovery.supportsAutoMerge) {
      return {
        ok: false,
        reason: 'AUTO_MERGE_NOT_ALLOWED',
        stderr: `Forgejo ${discovery.version} mist merge_when_checks_succeed in OpenAPI`,
      }
    }
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  // 1. Schedule-first: merge_when_checks_succeed-schedule. Bij fout surface we
  // de reden én skip de directe-merge-probe (de schedule-gate blijft
  // bindend: zonder schedule is er geen auto-merge).
  const scheduleBody: Record<string, unknown> = {
    Do: 'squash',
    merge_when_checks_succeed: true,
  }
  if (opts.expectedHeadSha) scheduleBody.head_commit_id = opts.expectedHeadSha

  const mergePath = `${repoPath(prRef.owner, prRef.repo)}/pulls/${prRef.index}/merge`

  try {
    await callForgejo(mergePath, {
      method: 'POST',
      write: true,
      host: prRef.host,
      json: scheduleBody,
    })
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  // 2. Opportunistische directe squash-merge met bounded retry (max 3
  // pogingen, voor transiënte mergeability). Falen blijft de schedule op
  // z'n plek: mode 'scheduled'.
  const directBody: Record<string, unknown> = { Do: 'squash' }
  if (opts.expectedHeadSha) directBody.head_commit_id = opts.expectedHeadSha

  const backoffMs = opts.directMergeBackoffMs ?? 500
  for (let attempt = 1; attempt <= 3; attempt++) {
    if (attempt > 1 && backoffMs > 0) {
      await new Promise((r) => setTimeout(r, backoffMs))
    }
    try {
      await callForgejo(mergePath, {
        method: 'POST',
        write: true,
        host: prRef.host,
        json: directBody,
      })
      return { ok: true, mode: 'merged' }
    } catch {
      // probeer opnieuw (bounded) of behoud de schedule.
    }
  }

  console.warn(`[enableAutoMergeOnPr] directe merge faalde na 3 pogingen voor ${opts.prUrl}; schedule blijft staan`)
  return { ok: true, mode: 'scheduled' }
}
```

