  const scheduleBody: Record<string, unknown> = { Do: 'squash', merge_when_checks_succeed: true }
  if (opts.expectedHeadSha) scheduleBody.head_commit_id = opts.expectedHeadSha
  try {
    await callForgejo(mergePath, { method: 'POST', write: true, host, json: scheduleBody })
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  // 2. Opportunistic direct merge, bounded retry x3.
  const directBody: Record<string, unknown> = { Do: 'squash' }
  if (opts.expectedHeadSha) directBody.head_commit_id = opts.expectedHeadSha
  const backoff = opts.directMergeBackoffMs ?? 0
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      await callForgejo(mergePath, { method: 'POST', write: true, host, json: directBody })
      return { ok: true, mode: 'merged' }
    } catch (err) {
      if (attempt < 3) await new Promise(r => setTimeout(r, backoff * attempt)) // or just backoff
    }
  }
  console.warn(`[enableAutoMergeOnPr] directe merge faalde na 3 pogingen voor ${prRef...}; schedule blijft staan`)
  return { ok: true, mode: 'scheduled' }
}
