  // 1. Schedule-first: POST met merge_when_checks_succeed (respecteert de
  //    "Allow auto-merge"-gate). Fout → surfacen; géén directe fallback.
  const scheduleBody: Record<string, unknown> = {
    Do: 'squash',
    merge_when_checks_succeed: true,
  }
  if (opts.expectedHeadSha) scheduleBody.head_commit_id = opts.expectedHeadSha

  try {
    await callForgejo(mergePath, {
      method: 'POST',
      write: true,
      host: prRef.host,
      json: scheduleBody,
    })
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  // 2. Opportunistische directe squash-merge in een max-3 bounded-retry-lus.
  //    Slagt direct → de PR staat al op main. Fout → de schedule van
  //    stap 1 blijft gewoon actief (checks draaien nog, head-mismatch, …).
  const directBody: Record<string, unknown> = { Do: 'squash' }
  if (opts.expectedHeadSha) directBody.head_commit_id = opts.expectedHeadSha

  const maxAttempts = 3
  const backoffMs = opts.directMergeBackoffMs ?? 250
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      await callForgejo(mergePath, {
        method: 'POST',
        write: true,
        host: prRef.host,
        json: directBody,
      })
      return { ok: true, mode: 'merged' }
    } catch (err) {
      if (attempt === maxAttempts) break
      console.warn(
        `[enableAutoMergeOnPr] directe merge poging ${attempt}/${maxAttempts} mislukt: ${
          (err as Error).message.slice(0, 200)
        }`,
      )
      if (backoffMs > 0) await new Promise((r) => setTimeout(r, backoffMs))
    }
  }
  console.warn(
    `[enableAutoMergeOnPr] directe merge faalde na ${maxAttempts} pogingen voor ${opts.prUrl}; schedule blijft actief`,
  )
  return { ok: true, mode: 'scheduled' }
}"}

